@@ -0,0 +1,22 @@
+--TEST--
+JIT ASSIGN_OP: 008 Arrays merging with itself
+--INI--
+opcache.enable=1
+opcache.enable_cli=1
+opcache.file_update_protection=0
+opcache.jit_buffer_size=1M
+--FILE--
+<?php
+function test() {
+       $a = [];
+    for ($i = 0; $i < 2; $i++) {
+        $a + $a += $a;
+        $a['b'] += 1;
+    }
+}
+test();
+?>
+DONE
+--EXPECTF--
+Warning: Undefined array key "b" in %sassign_op_008.php on line 6
+DONE
